if(studioPlan.priceUsd!==0||studioPlan.checkoutEnabled!==false||studioPlan.requiresPaymentMethod!==false)throw Error('Document Studio Pro must be free: USD 0, no checkout/payment method');

const locales=['ar','en','fr'];
