const adsEnabled=String(process.env.ENABLE_ADSENSE||cfg.enableAdsense||'false')==='true';
const googleSiteVerification=(process.env.GOOGLE_SITE_VERIFICATION||'').trim();
const umamiWebsiteId=(process.env.UMAMI_WEBSITE_ID||'').trim();
const audienceShareUrl=(process.env.AUDIENCE_SHARE_URL||'').trim();
if(umamiWebsiteId&&!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(umamiWebsiteId))throw Error('Expected a valid Umami Website ID (UUID)');
const repoForIssues=/^[a-z0-9_.-]+\/[a-z0-9_.-]+$/i.test(process.env.GITHUB_REPOSITORY||'') ? process.env.GITHUB_REPOSITORY : 'ribhlab/ribhlab.github.io';
if(googleSiteVerification && !/^[a-zA-Z0-9_\-=]{10,128}$/.test(googleSiteVerification))throw new Error('Invalid Google Search Console site verification token');
if(domain && !/^https:\/\/[a-z0-9.-]+(?::\d+)?(?:\/[a-z0-9._~-]+)*$/i.test(domain)) throw new Error('SITE_URL must be a full https:// URL, optionally with a project path');
const basePath=domain ? new URL(domain).pathname.replace(/\/$/,'') : '';
if (publisher && !/^ca-pub-\d{16}$/.test(publisher)) throw new Error('Publisher ID must look like ca-pub-XXXXXXXXXXXXXXXX');
if (adsEnabled && !/^ca-pub-\d{16}$/.test(publisher)) throw new Error('Set a valid ca-pub-XXXXXXXXXXXXXXXX publisher ID before enabling ads');
const files=fs.readdirSync(path.join(root,'content/articles')).filter(x=>x.endsWith('.json'));
const articles=files.map(file=>JSON.parse(fs.readFileSync(path.join(root,'content/articles',file),'utf8'))).sort((a,b)=>b.date.localeCompare(a.date)||a.slug.localeCompare(b.slug));
// Discoverable editorial sections, including lifestyle, with URLs by broad category.
const editorialSections=JSON.parse(fs.readFileSync(path.join(root,'content/sections.json'),'utf8')).sections;
const articleBySlug=new Map(articles.map(a=>[a.slug,a]));
const articleSection=new Map();
const sectionById=new Map();
for(const section of editorialSections){
 if(sectionById.has(section.id)||!/^[a-z0-9-]+$/.test(section.id))throw Error('Invalid or duplicate section '+section.id);
 sectionById.set(section.id,section);
 if(section.publishedSlugs.length>section.targetArticles)throw Error('Section over target '+section.id);
 for(const slug of section.publishedSlugs){
  if(!articleBySlug.has(slug))throw Error('Editorial section references missing article '+slug);
  if(articleSection.has(slug))throw Error('Article listed in multiple sections '+slug);
  articleSection.set(slug,section.id);
 }
}
for(const article of articles)if(!articleSection.has(article.slug))throw Error('Unclassified article '+article.slug);
