function separateTools(l,fullContent){
 const t=i18n[l];
 const names={
 ar:['حاسبة المخاطر','تسعير العمل الحر','مولّد البرومبتات','قياس سرعة الإنترنت','حاسبة إعلانات الموقع','حاسبة العمولة','عائد إعلانات الألعاب','عداد الكلمات','مدقق JSON','حجم الصفقة ووقف الخسارة','Document Studio Pro — $0'],
 en:['Risk budget','Freelance quote','AI prompt builder','Internet speed test','Site ad revenue','Affiliate commission','Game ads simulator','Word counter','JSON validator','Position sizing','Document Studio Pro — $0'],
 fr:['Budget de risque','Tarif freelance','Créateur de prompts IA','Test de débit','Publicité du site','Commission affiliation','Publicités des jeux','Compteur de mots','Validateur JSON','Taille de position','Document Studio Pro — $0']
 }[l];
 const defs=[
 ['risk-calculator','risk-tool','01','TRADING'],
 ['freelance-pricing','fee-tool','02','BUSINESS'],
 ['prompt-builder','prompt-tool','03','AI'],
 ['speed-test','speed-tool','04','INTERNET'],
 ['ad-revenue','rpm-tool','05','BUSINESS'],
 ['affiliate-commission','affiliate-tool','06','BUSINESS'],
 ['game-revenue','game-revenue-tool','07','GAMING'],
 ['word-counter','word-counter','08','WRITING'],
 ['json-validator','json-formatter','09','DEVELOPMENT'],
 ['position-size','position-sizer','10','TRADING'],
 ['document-studio','document-studio','11','DOCUMENTS']
 ];
 const found=[];
 const toolOpen=/<section class="tool-card[^"]*" id="([^"]+)"[^>]*>/g;
 for(const match of fullContent.matchAll(toolOpen)){
  const nested=/<\/?section\b[^>]*>/g;
  nested.lastIndex=match.index;
  let depth=0,end=-1;
  for(let tag;(tag=nested.exec(fullContent));){
   if(tag[0].startsWith('</'))depth--;else depth++;
   if(depth===0){end=nested.lastIndex;break;}
  }
  if(end<0)throw Error('Unbalanced nested <section> inside tool '+match[1]);
  found.push([match[1],fullContent.slice(match.index,end)]);
 }
 const sections=new Map(found);
 for(let k=0;k<defs.length;k++){
  const [slug,id,num,tag]=defs[k],section=sections.get(id);
  if(!section)throw Error('Interactive tool markup missing: '+id);
  const name=names[k];
  const intro='<section class="page-hero compact-hero"><div class="shell"><nav class="breadcrumbs"><a href="/'+l+'/">'+esc(t.navHome)+'</a><span>/</span><a href="/'+l+'/tools/">'+esc(t.tools)+'</a></nav><span class="section-kicker">RIBHLAB / '+tag+'</span><h1>'+esc(name)+'</h1><p>'+esc(t.toolsDesc)+'</p></div></section>';
  const content=intro+'<div class="shell tool-layout isolated-tool-layout">'+section+'</div><div class="shell tiny-note">'+esc(t.noReturn)+'</div>';
  page(l,{title:name+' | RibhLab',desc:name+' — '+t.toolsDesc,route:'/'+l+'/tools/'+slug+'/',content,active:'tools'});
 }
 const index='<section class="page-hero"><div class="shell"><span class="section-kicker">RIBHLAB / TOOLKIT</span><h1>'+esc(t.toolsTitle)+'</h1><p>'+esc(t.toolsDesc)+'</p></div></section><section class="section shell"><div class="section-head"><h2>'+esc(t.tools)+'</h2></div><div class="utility-grid">'+defs.map(([slug,id,num,tag],k)=>'<a class="utility-item" href="/'+l+'/tools/'+slug+'/"><span class="utility-number">'+num+'</span><span class="utility-group">'+tag+'</span><h3>'+esc(names[k])+'</h3><span class="utility-launch">'+esc(({ar:'فتح الأداة',en:'Open tool',fr:'Ouvrir l’outil'})[l])+' ↗</span></a>').join('')+'</div></section>';
 page(l,{title:t.toolsTitle+' | RibhLab',desc:t.toolsDesc,route:'/'+l+'/tools/',content:index,active:'tools'});
}
function toolPage(l){const t=i18n[l],content=`<section class="page-hero"><div class="shell"><nav class="breadcrumbs"><a href="/${l}/">${esc(t.navHome)}</a><span>/</span><span>${esc(t.tools)}</span></nav><span class="section-kicker">RIBHLAB / INTERACTIVE LAB</span><h1>${esc(t.toolsTitle)}</h1><p>${esc(t.toolsDesc)}</p></div></section><div class="shell tool-layout"><section class="tool-card" id="risk-tool"><div class="tool-tag">01 / RISK</div><h2>${esc(t.riskTitle)}</h2><div class="tool-form"><label>${esc(t.capital)}<input type="number" id="risk-capital" min="0" step="0.01" value="10000"></label><label>${esc(t.riskPct)}<input type="number" id="risk-percent" min="0" max="100" step="0.1" value="1"></label><label>${esc(t.currency)}<select id="risk-currency"><option value="MAD">MAD</option><option value="USD">USD</option><option value="EUR">EUR</option></select></label></div><div class="tool-result"><span>${esc(t.riskOutput)}</span><strong id="risk-result" aria-live="polite">100.00 MAD</strong></div><p class="tool-hint">${esc(t.riskHint)}</p></section><section class="tool-card" id="fee-tool"><div class="tool-tag">02 / FREELANCE</div><h2>${esc(t.feeTitle)}</h2><div class="tool-form"><label>${esc(t.hours)}<input type="number" id="fee-hours" min="0" step="0.5" value="8"></label><label>${esc(t.hourRate)}<input type="number" id="fee-hourly" min="0" step="1" value="150"></label><label>${esc(t.expenses)}<input type="number" id="fee-expenses" min="0" step="1" value="100"></label><label>${esc(t.feePct)}<input type="number" id="fee-platform" min="0" max="99" step="0.1" value="20"></label></div><div class="tool-result"><span>${esc(t.priceResult)}</span><strong id="fee-result" aria-live="polite">1,444.44</strong></div><p class="tool-hint">${esc(t.priceHint)}</p></section><section class="tool-card tool-wide" id="prompt-tool"><div class="tool-tag">03 / AI PROMPT BUILDER</div><h2>${esc(t.promptTitle)}</h2><div class="tool-form"><label>${esc(t.goal)}<input id="prompt-goal" placeholder="${esc(t.promptExample)}"></label><label>${esc(t.context)}<textarea id="prompt-context" rows="3"></textarea></label><label>${esc(t.constraints)}<textarea id="prompt-constraints" rows="3"></textarea></label><label>${esc(t.format)}<input id="prompt-format"></label></div><div class="prompt-controls"><button class="btn btn-primary" id="create-prompt" type="button">${esc(t.buildPrompt)} ↗</button><button class="btn btn-neutral" id="copy-prompt" type="button">${esc(t.copy)}</button></div><label class="visually-hidden" for="prompt-output">Prompt</label><textarea readonly rows="8" id="prompt-output" class="prompt-result" aria-live="polite"></textarea></section>${speedTool(l)}${monetizationTools(l)}${globalUtilityTools(l)}${positionSizerTool(l)}${documentStudioTool(l)}</div><div class="shell tiny-note">${esc(t.noReturn)}</div>`;
 separateTools(l,content);
}
